```go
package hpqueue

import (
	"runtime"
	"sync/atomic"
)

// maxThreads bounds the number of participant goroutines that may register
// with a single Domain.  Each participant owns domainSlots hazard slots.
const (
	maxThreads  = 512
	domainSlots = 2
)

// node is a single queue cell.  value is written once when the node is
// published and read only through a hazard pointer; next is the lock-free
// link.  freed is only used by the unsafe (immediate-reclamation) variant to
// poison a cell after it is unlinked.
type node struct {
	value any
	next  atomic.Pointer[node]
	freed atomic.Bool
}

// Domain owns the global array of hazard slots and hands out per-thread
// handles.  It is the unit of reclamation: every thread registered with a
// Domain can see (and therefore protect against) every other thread's slots.
type Domain struct {
	// slots[thread][slot] holds a strong reference to the node the thread is
	// currently protecting.  Because it is a *Go pointer stored in an atomic
	// pointer*, the garbage collector also treats it as a root: a protected
	// node can never be collected while a hazard slot references it.  That is
	// the language-level half of "no use-after-free".
	slots [maxThreads][domainSlots]atomic.Pointer[node]
	n     atomic.Int32

	// stats
	freed atomic.Int64 // nodes observed freed by the GC finalizer
	uaf   atomic.Int64 // nodes finalized while some hazard slot still held them
}

// NewDomain creates a hazard-pointer domain.
func NewDomain() *Domain { return &Domain{} }

// Thread is a per-goroutine handle.  A goroutine MUST NOT be used from more
// than one goroutine at a time (hazard slots are not themselves shared).
type Thread struct {
	d       *Domain
	idx     int
	retired []*node
	// reclaimBatch is the retire-list length at which the thread scans all
	// hazard slots and frees unprotected nodes.
	reclaimBatch int
}

// Register returns a Thread handle bound to d.  Each producer/consumer
// goroutine calls Register exactly once.
func (d *Domain) Register() *Thread {
	i := int(d.n.Add(1)) - 1
	if i >= maxThreads {
		panic("hpqueue: too many registered threads")
	}
	// Keep the global hazard array live for the GC; it is part of the domain.
	return &Thread{d: d, idx: i, reclaimBatch: 64}
}

func (t *Thread) protect(slot int, n *node) {
	t.d.slots[t.idx][slot].Store(n)
}

func (t *Thread) clear(slot int) {
	t.d.slots[t.idx][slot].Store(nil)
}

// retire unlinks a node from the caller's view and either frees it now (if it
// is provably un-referenced) or defers it until the next reclamation pass.
func (t *Thread) retire(n *node) {
	t.retired = append(t.retired, n)
	if len(t.retired) >= t.reclaimBatch {
		t.Reclaim()
	}
}

// Reclaim frees every retired node that is not protected by any hazard slot in
// the domain.  Off the hot path, so a short-lived heap allocation is fine.
func (t *Thread) Reclaim() {
	if len(t.retired) == 0 {
		return
	}
	protected := make(map[*node]struct{}, 32)
	for i := 0; i < int(t.d.n.Load()); i++ {
		for s := 0; s < domainSlots; s++ {
			if p := t.d.slots[i][s].Load(); p != nil {
				protected[p] = struct{}{}
			}
		}
	}
	kept := t.retired[:0]
	for _, n := range t.retired {
		if _, ok := protected[n]; ok {
			kept = append(kept, n)
		} else {
			freeNode(n)
		}
	}
	// Zero the tail of the slice so the backing array does not keep freed
	// nodes alive.
	for i := len(kept); i < len(t.retired); i++ {
		t.retired[i] = nil
	}
	t.retired = kept
}

// Flush frees all currently unprotected retired nodes.  Called once at the end
// of a run so the leak/finalizer accounting is exact.
func (t *Thread) Flush() { t.Reclaim() }

// freeNode breaks the link chain and drops all references to n.  The GC
// finalizer installed by newNode records the collection.
func freeNode(n *node) {
	n.next.Store(nil)
	n.value = nil
	runtime.KeepAlive(n)
}

// newNode allocates a node and installs the accounting finalizer.
//
// The finalizer is the "prove no use-after-free / no leak" instrumentation:
//   - domain.freed counts every node the GC actually reclaimed.
//   - domain.uaf counts nodes reclaimed while still present in a hazard slot.
//
// A correct hazard-pointer run therefore has uaf == 0 and, after a full drain,
// freed == number of successful dequeues.
func (d *Domain) newNode(v any) *node {
	n := &node{value: v}
	runtime.SetFinalizer(n, func(n *node) {
		for i := 0; i < int(d.n.Load()); i++ {
			for s := 0; s < domainSlots; s++ {
				if d.slots[i][s].Load() == n {
					d.uaf.Add(1)
					return
				}
			}
		}
		d.freed.Add(1)
	})
	return n
}

// GCTick forces a GC cycle and yields so finalizers can run.  Used by tests.
func (d *Domain) GCTick() {
	runtime.GC()
	runtime.Gosched()
}

// WaitFreed spins (forcing GC) until at least want nodes have been finalized,
// or the attempt budget is exhausted.  Returns the final count.
func (d *Domain) WaitFreed(want int64) int64 {
	for i := 0; i < 1000; i++ {
		if d.freed.Load()+d.uaf.Load() >= want {
			break
		}
		runtime.GC()
		runtime.Gosched()
	}
	return d.freed.Load()
}
