#### `queue.go`
```go
package hpqueue

import "sync/atomic"

// Queue is a lock-free MPMC queue (Michael–Scott linked list) with hazard
// pointer safe memory reclamation.  There is deliberately no ABA guard word:
// correctness comes from the invariant that a node is never released while a
// hazard slot references it.
//
// Invariants:
//   - head always points at a dummy node that is (or recently was) in the list.
//   - tail lags: it may point at a node that is not the last node.
//   - dequeue protects head and head.next before touching them.
//   - enqueue protects the tail it is about to dereference.
type Queue struct {
	head atomic.Pointer[node]
	tail atomic.Pointer[node]
	d    *Domain
}

// NewQueue returns an empty queue whose dummy head is the first node tracked
// by the domain.
func NewQueue() *Queue {
	d := NewDomain()
	dummy := d.newNode(nil)
	q := &Queue{d: d}
	q.head.Store(dummy)
	q.tail.Store(dummy)
	return q
}

// Domain exposes the accounting domain (finalizer counts, etc.).
func (q *Queue) Domain() *Domain { return q.d }

// Register returns a per-goroutine handle used by Enqueue/Dequeue.
func (q *Queue) Register() *Thread { return q.d.Register() }

// Enqueue appends v.  Lock-free and safe against concurrent dequeue.
func (q *Queue) Enqueue(t *Thread, v any) {
	n := q.d.newNode(v)
	for {
		tail := q.tail.Load()
		t.protect(0, tail)
		// Re-validate after publishing the hazard pointer.  If tail moved,
		// some other thread may be retiring the node we just grabbed; retry.
		if q.tail.Load() != tail {
			continue
		}
		next := tail.next.Load()
		if q.tail.Load() != tail {
			continue
		}
		if next == nil {
			if tail.next.CompareAndSwap(nil, n) {
				// Best-effort tail update; a lagging tail is fine.
				q.tail.CompareAndSwap(tail, n)
				t.clear(0)
				return
			}
		} else {
			// Help advance a lagging tail.  We never dereference next, so it
			// does not need a hazard slot of its own.
			q.tail.CompareAndSwap(tail, next)
		}
	}
}

// Dequeue removes and returns the oldest value.
func (q *Queue) Dequeue(t *Thread) (any, bool) {
	for {
		// Drop any hazard slot left over from a previous failed attempt so it
		// cannot pin an already-unlinked node forever.
		t.clear(1)
		head := q.head.Load()
		t.protect(0, head)
		if q.head.Load() != head {
			continue
		}
		tail := q.tail.Load()
		next := head.next.Load()
		if q.head.Load() != head {
			continue
		}
		if head == tail {
			if next == nil {
				t.clear(0)
				return nil, false
			}
			// Lagging tail: help move it forward.
			q.tail.CompareAndSwap(tail, next)
			continue
		}
		if next == nil {
			// head != tail but no successor: transient; retry.
			continue
		}
		// Protect the node we are about to read the value from, then
		// re-validate that head still equals the node we protected.
		t.protect(1, next)
		if q.head.Load() != head {
			continue
		}
		v := next.value
		if q.head.CompareAndSwap(head, next) {
			// Unlink succeeded.  Clear our own protection before retiring so
			// this thread's reclamation pass cannot keep the node forever.
			t.clear(0)
			t.clear(1)
			t.retire(head)
			return v, true
		}
	}
}
