#### `queue_unsafe.go` (the deliberately broken variant, for the demo)
```go
package hpqueue

import "sync"

// UnsafeQueue is the *same* Michael–Scott algorithm but with immediate
// reclamation: a node is poisoned and returned to the allocator as soon as it
// is unlinked, without waiting for hazard pointers.  It exists solely to
// demonstrate the use-after-free / corruption the safe Queue prevents.
//
// Do not use this in production.  Run it under -race and watch it fail.
type UnsafeQueue struct {
	head unsafeNodePtr
	tail unsafeNodePtr

	mu    sync.Mutex
	pool  []*node
	reuse int64
	freed int64
}

// unsafeNodePtr is a plain (non-atomic, intentionally racy) pointer used by
// the unsafe variant.
type unsafeNodePtr struct {
	p *node
}

// NewUnsafeQueue creates an empty queue.  Note: this variant is NOT lock-free;
// the allocator uses a mutex.  That is irrelevant to the bug being shown.
func NewUnsafeQueue() *UnsafeQueue {
	n := &node{}
	return &UnsafeQueue{head: unsafeNodePtr{n}, tail: unsafeNodePtr{n}}
}

func (u *UnsafeQueue) malloc(v any) *node {
	u.mu.Lock()
	if len(u.pool) > 0 {
		n := u.pool[len(u.pool)-1]
		u.pool = u.pool[:len(u.pool)-1]
		u.reuse++
		u.mu.Unlock()
		n.value = v
		n.freed.Store(false)
		return n
	}
	u.mu.Unlock()
	return &node{value: v}
}

// recycle is the bug: it publishes the unlinked node for reuse immediately.
func (u *UnsafeQueue) recycle(n *node) {
	n.value = nil       // poison -- races with any concurrent reader
	n.next.Store(nil)   // break link -- also races
	n.freed.Store(true) // mark as dead for the detector
	u.mu.Lock()
	u.pool = append(u.pool, n)
	u.freed++
	u.mu.Unlock()
}

func (u *UnsafeQueue) Enqueue(v any) {
	n := u.malloc(v)
	for {
		tail := u.tail.p
		next := tail.next.Load()
		if tail == u.tail.p {
			if next == nil {
				if tail.next.CompareAndSwap(nil, n) {
					u.tail.p = n
					return
				}
			} else {
				u.tail.p = next
			}
		}
	}
}

func (u *UnsafeQueue) Dequeue() (any, bool) {
	for {
		head := u.head.p
		tail := u.tail.p
		next := head.next.Load()
		if head == u.head.p {
			if head == tail {
				if next == nil {
					return nil, false
				}
				u.tail.p = next
				continue
			}
			if next == nil {
				continue
			}
			v := next.value
			// The correlator.  If the cell was recycled before we got here,
			// reading v above touched memory another goroutine already
			// reused/reset -> corruption.  This is the immediate-free bug.
			if next.freed.Load() {
				u.reuse++ // borrow counter to signal "observer saw a dead cell"
			}
			if head == u.head.p {
				u.head.p = next
				u.recycle(head) // <-- freed while others may still read it
				return v, true
			}
		}
	}
}

// Stats returns (recycled, reused) counts; used by the demo.
func (u *UnsafeQueue) Stats() (int64, int64) {
	u.mu.Lock()
	defer u.mu.Unlock()
	return u.freed, u.reuse
}
```

#### `queue_test.go`
```go
package hpqueue

import (
	"runtime"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

// TestGoodQueueExactlyOnce is the headline verification.  It runs the
// hazard-pointer MPMC queue with GOMAXPROCS=8 and N producers / M consumers,
// checks that every enqueued value is dequeued exactly once, and then uses GC
// finalizers to prove that (a) no node leaked and (b) no node was reclaimed
// while a hazard pointer still referenced it.
func TestGoodQueueExactlyOnce(t *testing.T) {
	old := runtime.GOMAXPROCS(8)
	defer runtime.GOMAXPROCS(old)

	const (
		producers = 8
		consumers = 8
		total     = 200000
	)

	q := NewQueue()
	domain := q.Domain()

	seen := make([]int32, total)
	var dequeued atomic.Int64

	producerThreads := make([]*Thread, producers)
	for p := 0; p < producers; p++ {
		producerThreads[p] = q.Register()
	}
	consumerThreads := make([]*Thread, consumers)
	for c := 0; c < consumers; c++ {
		consumerThreads[c] = q.Register()
	}

	var wg sync.WaitGroup
	start := make(chan struct{})

	for p := 0; p < producers; p++ {
		wg.Add(1)
		go func(p int) {
			defer wg.Done()
			t := producerThreads[p]
			<-start
			// Values are partitioned so every value 0..total-1 is produced
			// exactly once.
			for i := p; i < total; i += producers {
				q.Enqueue(t, i)
			}
		}(p)
	}

	var cwg sync.WaitGroup
	for c := 0; c < consumers; c++ {
		cwg.Add(1)
		go func(c int) {
			defer cwg.Done()
			t := consumerThreads[c]
			<-start
			for dequeued.Load() < total {
				v, ok := q.Dequeue(t)
				if !ok {
					runtime.Gosched()
					continue
				}
				idx := v.(int)
				atomic.AddInt32(&seen[idx], 1)
				dequeued.Add(1)
			}
		}(c)
	}

	close(start)
	wg.Wait()
	cwg.Wait()

	// Exactly-once check.
	dups, missing := 0, 0
	for i := 0; i < total; i++ {
		switch seen[i] {
		case 1:
		case 0:
			missing++
		default:
			dups++
		}
	}
	if dups != 0 || missing != 0 {
		t.Fatalf("exactly-once violated: dups=%d missing=%d", dups, missing)
	}
	if got := dequeued.Load(); got != total {
		t.Fatalf("dequeued=%d want %d", got, total)
	}

	// Flush every thread's retire list now that all goroutines are idle.
	for _, th := range producerThreads {
		th.Flush()
	}
	for _, th := range consumerThreads {
		th.Flush()
	}

	// Every successful dequeue retires exactly one node (the old dummy head),
	// so we expect `total` finalized nodes and exactly one live node (the
	// current dummy head).
	freed := domain.WaitFreed(total)
	deadline := time.Now().Add(5 * time.Second)
	for domain.uaf.Load() == 0 && domain.freed.Load() < total && time.Now().Before(deadline) {
		domain.GCTick()
		time.Sleep(time.Millisecond)
	}
	freed = domain.freed.Load()

	if got := domain.uaf.Load(); got != 0 {
		t.Fatalf("use-after-free: %d nodes finalized while hazard-protected", got)
	}
	if freed != total {
		t.Fatalf("leak: finalized=%d want %d", freed, total)
	}
	t.Logf("OK: values=%d exactly-once, freed=%d (== dequeues), uaf=0", total, freed)

	// Keep the queue (and therefore its live dummy head) reachable until here;
	// otherwise the GC could legitimately finalize the last node and skew the
	// accounting by one.
	runtime.KeepAlive(q)
}

// TestGoodQueueConcurrentMixed hammers the queue with concurrent enqueue and
// dequeue (not just produce-then-drain) and is meant to be run under -race.
func TestGoodQueueConcurrentMixed(t *testing.T) {
	const (
		workers = 16
		iters   = 50000
	)
	q := NewQueue()
	var ops atomic.Int64
	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func(w int) {
			defer wg.Done()
			th := q.Register()
			for i := 0; i < iters; i++ {
				if (i+w)&1 == 0 {
					q.Enqueue(th, i)
				} else {
					q.Dequeue(th)
				}
				ops.Add(1)
			}
			th.Flush()
		}(w)
	}
	wg.Wait()
	q.Domain().GCTick()
	if ops.Load() != workers*iters {
		t.Fatalf("ops=%d", ops.Load())
	}
}
