```go
// Command unsafe demonstrates the crash/corruption caused by switching
// reclamation to "free immediately after unlink" while the same Michael–Scott
// queue algorithm is running.
//
// Run it under the race detector:
//
//	go run -race ./cmd/unsafe
//
// Expected: WARNING: DATA RACE (and/or duplicate/missing values, and/or a nil
// dereference).  The safe implementation in the parent package does not do
// this; see queue_test.go.
package main

import (
	"fmt"
	"os"
	"runtime"
	"sync"
	"sync/atomic"
	"time"

	hpqueue "hpqueue"
)

const (
	producers = 8
	consumers = 8
	total     = 200000
)

func main() {
	runtime.GOMAXPROCS(8)

	q := hpqueue.NewUnsafeQueue()
	seen := make([]int32, total)
	var dequeued atomic.Int64

	start := make(chan struct{})
	stop := make(chan struct{})
	var wg sync.WaitGroup

	for p := 0; p < producers; p++ {
		wg.Add(1)
		go func(p int) {
			defer wg.Done()
			<-start
			for i := p; i < total; i += producers {
				q.Enqueue(i)
			}
		}(p)
	}
	for c := 0; c < consumers; c++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			defer func() {
				if r := recover(); r != nil {
					fmt.Printf("!! panic from corruption: %v\n", r)
					os.Exit(1)
				}
			}()
			<-start
			for dequeued.Load() < total {
				select {
				case <-stop:
					return
				default:
				}
				v, ok := q.Dequeue()
				if !ok {
					runtime.Gosched()
					continue
				}
				idx, ok := v.(int)
				if !ok || idx < 0 || idx >= total {
					// A cell was recycled and its value poisoned/changed
					// before this consumer read it.
					fmt.Printf("!! use-after-free: read invalid value %v\n", v)
					os.Exit(1)
				}
				atomic.AddInt32(&seen[idx], 1)
				dequeued.Add(1)
			}
		}()
	}

	close(start)
	// Watchdog: immediate reclamation frequently wedges the algorithm (a
	// reader follows a poisoned link and the queue state becomes inconsistent).
	// Without this the demo can spin forever inside Dequeue.
	time.AfterFunc(8*time.Second, func() {
		fmt.Println("!! deadlock/corruption: unsafe queue operations stuck")
		os.Exit(1)
	})
	go func() {
		time.Sleep(5 * time.Second)
		close(stop)
	}()
	wg.Wait()

	dups, missing := 0, 0
	for i := 0; i < total; i++ {
		switch seen[i] {
		case 1:
		case 0:
			missing++
		default:
			dups++
		}
	}
	f, reuse := q.Stats()
	fmt.Printf("dequeued=%d dups=%d missing=%d recycled=%d reused=%d\n",
		dequeued.Load(), dups, missing, f, reuse)
	if dups != 0 || missing != 0 || dequeued.Load() != total {
		fmt.Println("CORRUPTION CONFIRMED: immediate free loses or duplicates values")
		os.Exit(1)
	}
	fmt.Println("no corruption observed this run (try -race / rerun)")
}
